            Files.deleteIfExists(Path.of(dasar + akhiran + ".properties"));
        }
        for (int i = 0; i < akhiranDanIsi.length; i += 2) {
            Files.writeString(Path.of(dasar + akhiranDanIsi[i] + ".properties"), akhiranDanIsi[i + 1]);
        }
        ResourceBundle.clearCache();
    }
}

